<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/functions.php';
if($_SERVER['REQUEST_METHOD']!=='POST')jsonResponse('error','อนุญาตเฉพาะ POST',[],405);if(!isLoggedIn())jsonResponse('error','กรุณาเข้าสู่ระบบ',[],401);requireCsrf();
$db=(new Database())->getConnection();if(!$db)jsonResponse('error','ไม่สามารถเชื่อมต่อฐานข้อมูลได้',[],503);
if(($_POST['action']??'')!=='create')jsonResponse('error','คำสั่งไม่ถูกต้อง',[],400);
$orderId=(int)($_POST['order_id']??0);$reason=trim((string)($_POST['reason']??''));if(mb_strlen($reason)<10||mb_strlen($reason)>500)jsonResponse('error','กรุณาระบุเหตุผลอย่างน้อย 10 ตัวอักษรและไม่เกิน 500 ตัว',[],422);
try{$db->beginTransaction();$order=$db->prepare("SELECT id,order_no FROM orders WHERE id=? AND user_id=? AND order_status IN ('shipped','completed') FOR UPDATE");$order->execute([$orderId,(int)$_SESSION['user_id']]);$row=$order->fetch();if(!$row)throw new RuntimeException('ออเดอร์นี้ยังไม่เข้าเงื่อนไขการคืนสินค้า');$exists=$db->prepare("SELECT id FROM return_requests WHERE order_id=? AND status NOT IN ('rejected','cancelled') LIMIT 1");$exists->execute([$orderId]);if($exists->fetch())throw new RuntimeException('ออเดอร์นี้มีคำขอคืนสินค้าอยู่แล้ว');$db->prepare('INSERT INTO return_requests(order_id,user_id,reason) VALUES(?,?,?)')->execute([$orderId,(int)$_SESSION['user_id'],$reason]);createRoleNotification($db,'admin','return','มีคำขอคืนสินค้าใหม่','ออเดอร์ '.$row['order_no'].' รอตรวจสอบ',BASE_URL.'admin/returns.php');$db->commit();jsonResponse('success','ส่งคำขอคืนสินค้าแล้ว ทีมงานจะตรวจสอบโดยเร็ว');}catch(RuntimeException $e){if($db->inTransaction())$db->rollBack();jsonResponse('error',$e->getMessage(),[],409);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();jsonResponse('error','ไม่สามารถส่งคำขอได้',[],500);}
